INSERT INTO tblfestivals (FestivalName, StartDate, EndDate, DemandLevel, Verification, SourceUrl, Notes) SELECT 'Dashain 2026 (BS 2083)', '2026-10-11', '2026-10-25', 'high', 'official', 'https://www.moha.gov.np/page/government-and-public-holidays-in-2083', 'BS 2083 Asoj 25 - Kartik 8. Verification: 2+ sources. Ghatasthapana 2026-10-11 (Asoj 25); Fulpati 2026-10-17 (Asoj 31); Maha Ashtami 2026-10-18 (Kartik 1); Maha Navami 2026-10-20 (Kartik 3); Vijaya Dashami/Tika 2026-10-21 (Kartik 4); Ekadashi 2026-10-22 (Kartik 5); Kojagrat Purnima 2026-10-25 (Kartik 8). Official govt holiday block Asoj 31 - Kartik 6 = 2026-10-17 to 2026-10-23 (Fulpati to Dwadashi, MoHA gazette). DISAGREEMENTS: officeholidays.com lists Maha Ashtami 2026-10-19 (all others: 10-18; 10-19 is a ''Dashain holiday'' per Hamro Patro); stunningnepal.com lists Kojagrat Purnima 2026-10-26 (Kartik 9) vs 2026-10-25 (Kartik 8) per Ratopati/Panchang Samiti, Hamro Patro, nepcalendar, ashesh, officeholidays.' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tblfestivals WHERE FestivalName = 'Dashain 2026 (BS 2083)');
INSERT INTO tblfestivals (FestivalName, StartDate, EndDate, DemandLevel, Verification, SourceUrl, Notes) SELECT 'Tihar 2026 (BS 2083)', '2026-11-07', '2026-11-11', 'high', 'official', 'https://www.moha.gov.np/page/government-and-public-holidays-in-2083', 'BS 2083 Kartik 21 - 25. Verification: 2+ sources. Kaag Tihar 2026-11-07 (Kartik 21); Kukur Tihar + Laxmi Puja 2026-11-08 (Kartik 22, same day); Gai Tihar/Aunsi 2026-11-09 (ashesh); Govardhan Puja/Mha Puja/Nepal Sambat 1147 2026-11-10 (Kartik 24); Bhai Tika 2026-11-11 (Kartik 25). Govt holiday block Kartik 22-26 = 2026-11-08 to 2026-11-12 (Laxmi Puja to day after Bhai Tika). Consider demand window through 2026-11-12. No disagreements found.' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tblfestivals WHERE FestivalName = 'Tihar 2026 (BS 2083)');
INSERT INTO tblfestivals (FestivalName, StartDate, EndDate, DemandLevel, Verification, SourceUrl, Notes) SELECT 'Chhath 2026', '2026-11-15', '2026-11-15', 'high', 'official', 'https://www.moha.gov.np/page/government-and-public-holidays-in-2083', 'BS 2083 Kartik 29. Verification: 2+ sources. Main day (public holiday) 2026-11-15. The multi-day ritual (Nahay Khay to Usha Arghya, ~2026-11-12 to 11-16) is unverified. Strongest demand in Terai/Madhesh; falls days after Tihar, extending the travel peak.' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tblfestivals WHERE FestivalName = 'Chhath 2026');
INSERT INTO tblfestivals (FestivalName, StartDate, EndDate, DemandLevel, Verification, SourceUrl, Notes) SELECT 'Yomari Punhi / Dhanya Purnima / Udhauli 2026', '2026-12-24', '2026-12-24', 'medium', 'official', 'https://www.moha.gov.np/page/government-and-public-holidays-in-2083', 'BS 2083 Poush 9. Verification: 2+ sources. Nationwide public holiday per MoHA gazette. Adjacent to Christmas.' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tblfestivals WHERE FestivalName = 'Yomari Punhi / Dhanya Purnima / Udhauli 2026');
INSERT INTO tblfestivals (FestivalName, StartDate, EndDate, DemandLevel, Verification, SourceUrl, Notes) SELECT 'Christmas & English New Year week 2026-27', '2026-12-24', '2027-01-01', 'high', 'official', 'https://www.moha.gov.np/page/government-and-public-holidays-in-2083', 'BS 2083 Poush 9 - Poush 17. Verification: 2+ sources (Christmas only). Christmas 2026-12-25 (Poush 10) is an official public holiday. 2027-01-01 is NOT a public holiday in Nepal (absent from the MoHA 2083 list), but it is a tourist and domestic travel peak. Week also contains Yomari Punhi (12-24) and Tamu Lhosar (12-30).' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tblfestivals WHERE FestivalName = 'Christmas & English New Year week 2026-27');
