INSERT INTO tblfestivals (FestivalName, StartDate, EndDate, DemandLevel, Verification, SourceUrl, Notes) SELECT 'Dashain 2027 (BS 2084)', '2027-09-30', '2027-10-15', 'high', 'disagreement', 'https://www.ashesh.com.np/nepali-calendar/?year=2084&month=Ashwin', 'BS 2084 Asoj 13 - Asoj 28 (ashesh numbering). Verification: 2+ sources, with disagreement. Ghatasthapana 2027-09-30; Fulpati 2027-10-06; Maha Ashtami 2027-10-07 (all agree). DISAGREEMENT: Maha Navami 2027-10-08 / Vijaya Dashami 2027-10-09 / Kojagrat 2027-10-14 per drikpanchang (Kathmandu) and stunningnepal.com; vs Navami 2027-10-09 / Dashami 2027-10-10 / Kojagrat 2027-10-15 per ashesh.com.np. End date set to 2027-10-15 to cover both. BS numbering also differs: stunningnepal says Ghatasthapana Asoj 14, ashesh Asoj 13 (ashesh: Asoj 1 = 2027-09-18; rat32: Asoj 1 = 2027-09-17). Not official: Panchang Nirnayak Vikas Samiti is still collecting 2084 calendar submissions (deadline Asoj 20, 2083) and MoHA 2084 holiday list is unpublished. Re-check in early 2027.' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tblfestivals WHERE FestivalName = 'Dashain 2027 (BS 2084)');
