-- Festival and travel-peak calendar (additive). Edited in admin -> Festivals.
-- Seed data: docs/festival-calendar-sources.md (researched 2026-09-27). BS 2083 dates are from the
-- official MoHA holiday list; BS 2084 dates are from two independent calendars and must be
-- re-checked when the official 2084 list is published (normally Feb/Mar 2027).
CREATE TABLE IF NOT EXISTS `tblfestivals` (
  `id` int NOT NULL AUTO_INCREMENT,
  `FestivalName` varchar(150) NOT NULL,
  `StartDate` date NOT NULL,
  `EndDate` date NOT NULL,
  `DemandLevel` varchar(10) NOT NULL DEFAULT 'medium',
  `Verification` varchar(20) NOT NULL DEFAULT 'unverified',
  `SourceUrl` varchar(500) DEFAULT NULL,
  `Notes` text,
  `CreatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `UpdatedAt` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `Dates` (`StartDate`, `EndDate`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

